% -----------------------------------------------------------------------------
% versal_sar_backproject.tex
%
% 2/10/2025 Austin Owens (austin.t.owens@jpl.nasa.gov)
%
% Documentation for the implementation of SAR backprojection on AMD Versal ACAP
%
% -----------------------------------------------------------------------------
%
% -----------------------------------------------------------------------------
% Document preamble
% -----------------------------------------------------------------------------
%
\documentclass[10pt,twoside]{article}

% Math symbols
\usepackage{amsmath}
\usepackage{amssymb}

% Headers/Footers
\usepackage{fancyhdr}

% Colors
% See https://en.wikibooks.org/wiki/LaTeX/Colors
\usepackage[dvipsnames]{xcolor}

% Importing and manipulating graphics
\usepackage{graphicx}
\usepackage{subcaption}
\usepackage{pdflscape}
\usepackage{svg}
\usepackage{adjustbox}

% Captions
\usepackage[font=footnotesize,labelfont=bf,skip=1pt]{caption}

% Sections
\usepackage[section]{placeins}

% Glossary
\usepackage[acronym,automake]{glossaries-extra}
\setabbreviationstyle[acronym]{long-short}
\makeglossaries
\loadglsentries{sections/glossary}

% Misc packages
\usepackage{verbatim}
\usepackage{dcolumn}
\usepackage{ifpdf}
\usepackage[numbered,framed]{matlab-prettifier}
\usepackage{enumitem}


% PDF Bookmarks and hyperref stuff
\usepackage[
  bookmarks=true,
  bookmarksnumbered=true,
  colorlinks=true,
  filecolor=blue,
  linkcolor=blue,
  urlcolor=blue,
  hyperfootnotes=true,
  citecolor=blue
]{hyperref}

% Improved citation handling
% (include after the hyperref stuff)
\usepackage{cite}

% Pretty printing code
\usepackage{listings}

% Tables
\usepackage{booktabs}
\usepackage{siunitx}
\sisetup{
  detect-weight=true,
  detect-family=true,
  round-mode=places,
  round-precision=3,      % adjust displayed precision if you like
  table-number-alignment = center
}

% Syntax highlighting
% * Use OliveGreen for the comments to make them darker green
\lstset{
	language=C,
	basicstyle=\small\ttfamily,
	keywordstyle=\color{blue}\ttfamily,
	stringstyle=\color{red}\ttfamily,
	commentstyle=\color{OliveGreen}\ttfamily,
	tabsize=4,
	showstringspaces=false
}

% -----------------------------------------------------------------------------
% Setup the margins
% -----------------------------------------------------------------------------
% lists
\setlist[enumerate]{
    leftmargin=2em,
    labelsep=0.75em,
    labelwidth=1.5em,
    itemsep=0pt,
    topsep=1em,
    parsep=0pt
}

\setlist[itemize]{
    leftmargin=2em,
    labelsep=0.75em,
    labelwidth=1.5em,
    itemsep=0pt,
    topsep=1em,
    parsep=0pt
}

% Footer Template

% Set left margin - The default is 1 inch, so the following
% command sets a 1.25-inch left margin.
\setlength{\oddsidemargin}{0.25in}
\setlength{\evensidemargin}{0.25in}

% Set width of the text - What is left will be the right
% margin. In this case, right margin is
% 8.5in - 1.25in - 6in = 1.25in.
\setlength{\textwidth}{6in}

% Set top margin - The default is 1 inch, so the following
% command sets a 0.75-inch top margin.
%\setlength{\topmargin}{-0.25in}
\setlength{\topmargin}{-0.2in}

% Set height of the header
\setlength{\headheight}{0.3in}

% Set vertical distance between the header and the text
\setlength{\headsep}{0.2in}

% Set height of the text
\setlength{\textheight}{8.5in}

% Set vertical distance between the text and the
% bottom of footer
\setlength{\footskip}{0.4in}

% -----------------------------------------------------------------------------
% Allow floats to take up more space on a page.
% -----------------------------------------------------------------------------

% see page 142 of the Companion for this stuff and the
% documentation for the fancyhdr package
\renewcommand{\textfraction}{0.05}
\renewcommand{\topfraction}{0.95}
\renewcommand{\bottomfraction}{0.95}
% dont make this too small
\renewcommand{\floatpagefraction}{0.35}
\setcounter{totalnumber}{5}

% Make sure the top/bottom rules appear on the page
\renewcommand{\headrulewidth}{0.4pt}
\renewcommand{\footrulewidth}{0.4pt}

% -----------------------------------------------------------------------------
% Set up the header/footer
% -----------------------------------------------------------------------------
%
% First page
% - set the head/foot rule width to zero to hide them
\fancypagestyle{plain}{
	\renewcommand{\headrulewidth}{0pt}
	\renewcommand{\footrulewidth}{0pt}
	\fancyhf{}
	\fancyfoot{}
}

% All other pages
\lhead{SAR Backprojection on AMD Versal ACAP}
\chead{}
\rhead{\today}
\lfoot{}
\cfoot{}
\rfoot{\thepage}

% =============================================================================
% Document contents
% =============================================================================
%
\begin{document}
\title{SAR Backprojection on AMD Versal ACAP}
\author{Austin Owens (\texttt{\href{mailto:austin.t.owens@jpl.nasa.gov}{austin.t.owens@jpl.nasa.gov}}) \and
        David Hawkins (\texttt{\href{mailto:david.w.hawkins@jpl.nasa.gov}{david.w.hawkins@jpl.nasa.gov}})}
\date{\today}

% Title page
\maketitle

% Table of contents
\tableofcontents

% Switch to the fancy page style
\pagestyle{fancy}

% Start the first section on an odd page
%\cleardoublepage
\clearpage

% =============================================================================
% Main Document
% =============================================================================
%
\printglossary[type=\acronymtype,title=Abbreviations]
\clearpage
\input{sections/intro.tex}
\clearpage
\input{sections/versal_overview.tex}
\clearpage
\input{sections/implementation.tex}
\clearpage
\input{sections/performance_metrics.tex}
\clearpage
\input{sections/future_work.tex}
\clearpage
\appendix
\input{sections/appendix.tex}
\clearpage
%\input{sections/resources.tex}
%\clearpage
%\input{sections/ujtag.tex}
%\clearpage
%\input{sections/jtag_to_register.tex}
%\clearpage
%\input{sections/epilogue.tex}

%\clearpage
%------------------------------------------------------------------------------
% Do the bibliography
%------------------------------------------------------------------------------
%
% Note, you can't have spaces in the list of bibliography files
%
\bibliography{sections/refs}
\bibliographystyle{plain}

%------------------------------------------------------------------------------
\end{document}
